member.summary:
Represents the operation service of the GetAnimeList GraphQL operation

query GetAnimeList($perPage: Int, $page: Int) {
  Page(perPage: $perPage, page: $page) {
    __typename
    pageInfo {
      __typename
      total
      perPage
      currentPage
      lastPage
      hasNextPage
    }
    characters {
      __typename
      name {
        __typename
        first
        last
        native
        alternative
        alternativeSpoiler
        userPreferred
      }
      image {
        __typename
        large
        medium
      }
      gender
      dateOfBirth {
        __typename
        year
        month
        day
      }
      ... on Character {
        id
      }
    }
  }
}

